    pol_intro: "This Privacy Policy and Terms & Conditions govern your use of the RA Masala website and the purchase of our products. By accessing our website or placing an order, you agree to the practices described below.",
    pol_last_updated: "Last updated: August 2026. RA Masala reserves the right to amend this policy at any time.",
    pol_legal_tag: "LEGAL",
    pol_s10_item1: "For any questions regarding this policy, your personal data, or our terms, please contact us at:",
    pol_s10_item2: "Customer Care No: 7518166686",
    pol_s10_item3: "Email: ramasale@ymail.com / RAMASALE.6686@GMAIL.COM",
    pol_s10_title: "10. Contact Us",
    pol_s1_item1: "Personal details you provide at registration or checkout, such as your name, email address, phone number, shipping address, and payment details.",
    pol_s1_item2: "Order history, wishlist, and browsing behaviour used to improve our services and recommend relevant products.",
    pol_s1_item3: "Device and usage data (such as browser type, IP address, pages visited) collected automatically for analytics and security.",
    pol_s1_title: "1. Information We Collect",
    pol_s2_item1: "To process and deliver your orders, including order confirmations, invoices, and shipping updates.",
    pol_s2_item2: "To provide customer support and respond to your queries and feedback.",
    pol_s2_item3: "To personalise your shopping experience, send offers, and keep you informed about our products.",
    pol_s2_item4: "To maintain security, prevent fraud, and comply with legal obligations.",
    pol_s2_title: "2. How We Use Your Information",
    pol_s3_item1: "We never sell your personal information to third parties.",
    pol_s3_item2: "Your information is shared only with trusted partners who help us operate our store (such as payment gateways, logistics partners, and hosting providers) under strict confidentiality.",
    pol_s3_item3: "We may disclose information where required by law or to protect the rights and safety of RA Masala and its customers.",
    pol_s3_title: "3. Sharing of Information",
    pol_s4_item1: "We use industry-standard security measures, including encryption, to protect your personal data during transmission and storage.",
    pol_s4_item2: "Payment transactions are processed through secure, PCI-compliant payment gateways. We do not store your full card or payment credentials on our servers.",
    pol_s4_title: "4. Data Security",
    pol_s5_item1: "Our website uses cookies to remember your preferences, keep items in your cart, and improve performance.",
    pol_s5_item2: "You can disable cookies in your browser settings; however, some features of the site may not work correctly without them.",
    pol_s5_title: "5. Cookies",
    pol_s6_item1: "You may access, correct, or update your personal information anytime from your account.",
    pol_s6_item2: "You may request deletion of your account and personal data by contacting us.",
    pol_s6_item3: "You can opt out of promotional communications at any time.",
    pol_s6_title: "6. Your Rights",
    pol_s7_item1: "All orders are subject to product availability. We reserve the right to cancel any order due to unavailability of stock or payment issues.",
    pol_s7_item2: "Prices, taxes, and shipping charges are calculated at checkout and may change without prior notice.",
    pol_s7_item3: "Product images are indicative; actual product colour, size, and packaging may vary slightly.",
    pol_s7_item4: "Delivery timelines are estimates and may be affected by location, weather, or unforeseen circumstances.",
    pol_s7_item5: "Returns and refunds are governed by our return policy. If you receive a damaged or incorrect product, contact us within 48 hours of delivery.",
    pol_s7_item6: "Cash on Delivery (COD) orders are confirmed only after a successful verification call. We may cancel orders with repeated non-acceptance.",
    pol_s7_title: "7. Terms & Conditions",
    pol_s8_item1: "All content on this website, including text, logos, images, and branding, is the property of RA Masala and may not be reproduced without permission.",
    pol_s8_title: "8. Intellectual Property",
    pol_s9_item1: "We may update this Privacy Policy from time to time. Any changes will be posted on this page with the revised date.",
