    story_img_alt: "RA Masala Story",
    story_lead: "Founded in 1972 by Shri Ramchandra Vasant Divate (Bhau) and his wife Sou Vijaya Ramchandra Divate (Aai), R A Masale boasts a legacy of over 50 years of experience in the food industry.",
    story_network_desc: "We have a strong distribution network that connects us with culinary enthusiasts through a robust chain of super stockists and distributors across the state and beyond.",
    story_network_promise: "Every pack of RA Masala reflects our promise—raw materials roasted at optimum temperature to preserve essential oils, rich natural color, and unmatched flavor depth that brings your recipes alive.",
    story_network_title: "Growing Network, Everlasting Promise",
    story_p1: "The journey began humbly with the production of a small quantity of Onion Garlic Chutney. We started with a focus on producing the best possible product, and that commitment to quality and hard work has remained at the core of our business philosophy. As a family-owned and operated business, we have maintained a strong commitment to quality and customer satisfaction across generations.",
    story_p2: "This dedication has fueled consistent growth, transforming R A Masale from a small-scale operation into a leading manufacturer of spices and food products in Maharashtra. We have successfully modernized our production processes while preserving traditional recipes and quality standards. This approach allows us to offer a diverse range of products, including spices, ready-mix masalas, papads, pickles, and more, catering to a wide variety of culinary needs.",
    story_subtitle: "Established Since 1972",
    story_title: "A Legacy of Flavor & Purity Across Generations",
    story_value1_desc: "We prioritize quality in every aspect. We use only the finest, responsibly sourced raw ingredients to guarantee authentic taste.",
    story_value1_title: "Commitment to Purity",
    story_value2_desc: "Half a century of customer trust. Preserving traditional Maharashtrian recipes passed down generations.",
    story_value2_title: "50+ Years Legacy",
    story_value3_desc: "Contributing directly to local growth by providing stable livelihoods and employment opportunities to hundreds.",
    story_value3_title: "Local Empowerment",
