    story_img_alt: "आर.ए. मसाला की कहानी",
    story_lead: "१९७२ में श्री रामचंद्र वसंत दिवटे (भाऊ) और उनकी पत्नी सौ विजया रामचंद्र दिवटे (आई) द्वारा स्थापित, आर ए मसाले खाद्य उद्योग में ५० से अधिक वर्षों का अनुभव रखता है।",
    story_network_desc: "हमारा एक मजबूत वितरण नेटवर्क है जो हमें राज्य भर में और उससे आगे सुपर स्टॉकिस्टों और वितरकों की एक मजबूत श्रृंखला के माध्यम से जोड़ता है।",
    story_network_promise: "आरए मसाले का हर पैकेट हमारे वादे को दर्शाता है—आवश्यक तेलों, समृद्ध प्राकृतिक रंग और बेहतरीन स्वाद को बनाए रखने के लिए सही तापमान पर भुना हुआ कच्चा माल।",
    story_network_title: "बढ़ता नेटवर्क, शाश्वत वादा",
    story_p1: "इस यात्रा की शुरुआत प्याज लहसुन की चटनी के कम मात्रा में उत्पादन के साथ बहुत ही साधारण तरीके से हुई थी। हमने सर्वोत्तम उत्पाद बनाने के संकल्प के साथ शुरुआत की, और गुणवत्ता व कड़ी मेहनत के प्रति हमारी प्रतिबद्धता हमारे व्यवसाय के केंद्र में रही है। एक पारिवारिक स्वामित्व वाले व्यवसाय के रूप में, हम पीढ़ियों से गुणवत्ता और ग्राहक संतुष्टि के लिए प्रतिबद्ध हैं।",
    story_p2: "इस समर्पण ने निरंतर विकास को बढ़ावा दिया, जिससे आर ए मसाले एक लघु उद्योग से महाराष्ट्र में मसालों और खाद्य उत्पादों का एक अग्रणी निर्माता बन गया। हमने पारंपरिक रेसिपी और गुणवत्ता मानकों को बनाए रखते हुए अपनी उत्पादन प्रक्रियाओं को सफलतापूर्वक आधुनिक बनाया है। इससे हम मसालों, रेडी-मिक्स मसालों, पापड़, अचार जैसी विभिन्न उत्पादों की श्रृंखला प्रदान करते हैं।",
    story_subtitle: "१९७२ से स्थापित",
    story_title: "पिढ़ियों से स्वाद और शुद्धता की विरासत",
    story_value1_desc: "हम हर पहलू में गुणवत्ता को प्राथमिकता देते हैं। प्रामाणिक स्वाद की गारंटी के लिए हम केवल बेहतरीन और जिम्मेदारी से प्राप्त कच्चे माल का उपयोग करते हैं।",
    story_value1_title: "शुद्धता के प्रति प्रतिबद्धता",
    story_value2_desc: "आधी सदी का ग्राहकों का विश्वास। पीढ़ियों से चली आ रही पारंपरिक महाराष्ट्रीयन रेसिपी का संरक्षण।",
    story_value2_title: "५०+ वर्षों की विरासत",
    story_value3_desc: "सैकड़ों लोगों को स्थिर आजीविका और रोजगार के अवसर प्रदान करके स्थानीय विकास में सीधा योगदान देना।",
