    story_lead: "१९७२ मध्ये श्री रामचंद्र वसंत दिवटे (भाऊ) आणि त्यांच्या पत्नी सौ विजया रामचंद्र दिवटे (आई) यांनी स्थापन केलेल्या, आर ए मसाल्याला अन्न उद्योगातील ५० वर्षांहून अधिक अनुभवाचा वारसा लाभला आहे.",
    story_network_desc: "आमच्याकडे एक मजबूत वितरण नेटवर्क आहे जे आम्हाला राज्यभरात आणि त्यापलीकडे सुपर स्टॉकलिस्ट आणि वितरकांच्या मजबूत साखळीद्वारे जोडते.",
    story_network_promise: "आरए मसाल्याचा प्रत्येक पॅक आमचे वचन प्रतिबिंबित करतो—अस्सल सुगंध, मूळ तेल आणि उत्कृष्ट चव टिकवून ठेवण्यासाठी योग्य तापमानावर भाजलेला कच्चा माल.",
    story_network_title: "वाढते जाळे, शाश्वत वचन",
    story_p1: "या प्रवासाची सुरुवात कांदा लसूण चटणीच्या अल्प प्रमाणातील उत्पादनाने अगदी साधेपणाने झाली. आम्ही सर्वोत्तम उत्पादन बनवण्याच्या ध्यासाने सुरुवात केली, आणि दर्जेदार उत्पादन व कठोर परिश्रम हीच आमच्या व्यवसायाची मुख्य मूल्ये राहिली आहेत. कौटुंबिक व्यवसाय म्हणून आम्ही पिढ्यानपिढ्या गुणवत्ता आणि ग्राहक समाधानासाठी वचनबद्ध आहोत.",
    story_p2: "या समर्पणाने सातत्यपूर्ण वाढीस चालना दिली, ज्यामुळे आर ए मसाल्याचे रूपांतर एका छोट्या उद्योगातून महाराष्ट्रातील मसाले आणि अन्न उत्पादनांच्या अग्रगण्य उत्पादकात झाले. आम्ही पारंपारिक पाककृती आणि गुणवत्ता मानके जतन करताना आमच्या उत्पादन प्रक्रिया यशस्वीरित्या आधुनिक केल्या आहेत. यामुळे आम्ही मसाले, रेडी-मिक्स मसाले, पापड, लोणचे यांसारख्या विविध उत्पादनांची श्रेणी उपलब्ध करून देऊ शकतो.",
    story_subtitle: "१९७२ पासून स्थापित",
    story_title: "पिढ्यानपिढ्या चव आणि शुद्धतेचा वारसा",
    story_value1_desc: "आम्ही प्रत्येक बाबतीत गुणवत्तेला प्राधान्य देतो. अस्सल चवीची हमी देण्यासाठी आम्ही फक्त उत्कृष्ट आणि जबाबदारीने मिळवलेला कच्चा माल वापरतो.",
    story_value1_title: "शुद्धतेची हमी",
    story_value2_desc: "अर्ध्या शतकाचा ग्राहकांचा विश्वास. पिढ्यानपिढ्या चालत आलेल्या पारंपारिक महाराष्ट्रीयन पाककृतींचे जतन.",
    story_value2_title: "५०+ वर्षांचा वारसा",
    story_value3_desc: "शेकडो लोकांना स्थिर उपजीविका आणि रोजगाराच्या संधी देऊन स्थानिक विकासात थेट योगदान देणे.",
