    shop_title: "ನಮ್ಮ ಮಸಾಲೆಗಳ ಸಂಗ್ರಹವನ್ನು ಅನ್ವೇಷಿಸಿ",
    story_bags_alt: "ಮಸಾಲೆ ಬ್ಯಾಗ್‌ಗಳು",
    story_founders_title: "ನಮ್ಮ ಸ್ಥಾಪಕ ಸ್ತಂಭಗಳು",
    story_img_alt: "ಆರ್.ಎ. ಮಸಾಲಾ ಕಥೆ",
    story_lead: "೧೯೭೨ ರಲ್ಲಿ ಶ್ರೀ ರಾಮಚಂದ್ರ ವಸಂತ್ ದಿವಟೆ (ಭಾವು) ಮತ್ತು ಅವರ ಪತ್ನಿ ಸೌ ವಿಜಯಾ ರಾಮಚಂದ್ರ ದಿವಟೆ (ಆಯಿ) ಅವರಿಂದ ಸ್ಥಾಪಿಸಲ್ಪಟ್ಟ ಆರ್ ಎ ಮಸಾಲೆ ಆಹಾರ ಉದ್ಯಮದಲ್ಲಿ ೫೦ ಕ್ಕೂ ಹೆಚ್ಚು ವರ್ಷಗಳ ಅನುಭವದ ಪರಂಪರೆಯನ್ನು ಹೊಂದಿದೆ.",
    story_network_desc: "ರಾಜ್ಯದಾದ್ಯಂತ ಮತ್ತು ಅದಕ್ಕೂ ಮೀರಿ ಸೂಪರ್ ಸ್ಟಾಕಿಸ್ಟ್‌ಗಳು ಮತ್ತು ವಿತರಕರ ಭದ್ರವಾದ ಸರಪಳಿಯ ಮೂಲಕ ಗ್ರಾಹಕರನ್ನು ನಮ್ಮೊಂದಿಗೆ ಸಂಪರ್ಕಿಸುವ ಬಲಿಷ್ಠ ವಿತರಣಾ ಜಾಲವನ್ನು ನಾವು ಹೊಂದಿದ್ದೇವೆ.",
    story_network_promise: "ಆರ್ಎ ಮಸಾಲಾದ ಪ್ರತಿ ಪ್ಯಾಕ್ ನಮ್ಮ ಭರವಸೆಯನ್ನು ಪ್ರತಿಬಿಂಬಿಸುತ್ತದೆ-ಅಗತ್ಯ ತೈಲಗಳು, ಶ್ರೀಮಂತ ನೈಸರ್ಗಿಕ ಬಣ್ಣ ಮತ್ತು ಸಾಟಿಯಿಲ್ಲದ ಪರಿಮಳದ ಆಳವನ್ನು ಸಂರಕ್ಷಿಸಲು ಸೂಕ್ತವಾದ ತಾಪಮಾನದಲ್ಲಿ ಹುರಿದ ಕಚ್ಚಾ ವಸ್ತುಗಳು.",
    story_network_title: "ಬೆಳೆಯುತ್ತಿರುವ ನೆಟ್‌ವರ್ಕ್, ಶಾಶ್ವತ ಭರವಸೆ",
    story_p1: "ಈ ಪ್ರಯಾಣವು ಈರುಳ್ಳಿ ಬೆಳ್ಳುಳ್ಳಿ ಚಟ್ನಿಯ ಸಣ್ಣ ಪ್ರಮಾಣದ ಉತ್ಪಾದನೆಯೊಂದಿಗೆ ವಿನಮ್ರವಾಗಿ ಪ್ರಾರಂಭವಾಯಿತು. ನಾವು ಸಾಧ್ಯವಾದಷ್ಟು ಉತ್ತಮವಾದ ಉತ್ಪನ್ನವನ್ನು ತಯಾರಿಸುವತ್ತ ಗಮನಹರಿಸಿ ಪ್ರಾರಂಭಿಸಿದ್ದೇವೆ, ಮತ್ತು ಗುಣಮಟ್ಟ ಹಾಗೂ ಕಠಿಣ ಪರಿಶ್ರಮದ ಬದ್ಧತೆಯು ನಮ್ಮ ವ್ಯವಹಾರದ ತಿರುಳಾಗಿದೆ.",
    story_p2: "ಈ ಸಮರ್ಪಣೆ ನಿರಂತರ ಬೆಳವಣಿಗೆಯನ್ನು ಉತ್ತೇಜಿಸಿತು, ಆರ್ ಎ ಮಸಾಲೆಯನ್ನು ಸಣ್ಣ ಪ್ರಮಾಣದ ಕಾರ್ಯಾಚರಣೆಯಿಂದ ಮಹಾರಾಷ್ಟ್ರದ ಪ್ರಮುಖ ಮಸಾಲೆಗಳು ಮತ್ತು ಆಹಾರ ಉತ್ಪನ್ನಗಳ ತಯಾರಕರಾಗಿ ಪರಿವರ್ತಿಸಿತು. ನಾವು ಸಾಂಪ್ರದಾಯಿಕ ಪಾಕವಿಧಾನಗಳನ್ನು ಮತ್ತು ಗುಣಮಟ್ಟವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳುವ ಮೂಲಕ ನಮ್ಮ ಉತ್ಪಾದನಾ ಪ್ರಕ್ರಿಯೆಯನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಆಧುನೀಕರಿಸಿದ್ದೇವೆ.",
    story_subtitle: "೧೯೭೨ ರಿಂದ ಸ್ಥಾಪಿತವಾಗಿದೆ",
    story_title: "ಪೀಳಿಗೆಯಿಂದ ಪೀಳಿಗೆಗೆ ರುಚಿ ಮತ್ತು ಶುದ್ಧತೆಯ ಪರಂಪರೆ",
    story_value1_desc: "ನಾವು ಪ್ರತಿಯೊಂದು ವಿಷಯದಲ್ಲೂ ಗುಣಮಟ್ಟಕ್ಕೆ ಆದ್ಯತೆ ನೀಡುತ್ತೇವೆ. ಅಧಿಕೃತ ರುಚಿಯನ್ನು ಖಾತರಿಪಡಿಸಲು ನಾವು ಅತ್ಯುತ್ತಮವಾದ, ಜವಾಬ್ದಾರಿಯುತ ಕಚ್ಚಾ ಪದಾರ್ಥಗಳನ್ನು ಬಳಸುತ್ತೇವೆ.",
    story_value1_title: "ಶುದ್ಧತೆಗೆ ಬದ್ಧತೆ",
    story_value2_desc: "ಅರ್ಧ ಶತಮಾನದ ಗ್ರಾಹಕರ ವಿಶ್ವಾಸ. ಪೀಳಿಗೆಯಿಂದ ಬಂದ ಸಾಂಪ್ರದಾಯಿಕ ಮಹಾರಾಷ್ಟ್ರದ ಪಾಕವಿಧಾನಗಳನ್ನು ಸಂರಕ್ಷಿಸುವುದು.",
